/* From Uiverse.io by Satwinder04 - Tags: loader */
.__UIV_SCOPE__ .loader {
  position: relative;
  width: 164px;
  height: 100px;
  margin: 50px auto;
}

.__UIV_SCOPE__ .loader div {
  position: absolute;
  width: 10px;
  height: 30px;
  background-color: #ff6a00;
  border-radius: 5px;
  animation: loader_51899 1.5s ease-in-out infinite;
}

.__UIV_SCOPE__ .loader .bar1 {
  left: 0px;
  animation-delay: 0s;
}

.__UIV_SCOPE__ .loader .bar2 {
  left: 20px;
  animation-delay: 0.15s;
}

.__UIV_SCOPE__ .loader .bar3 {
  left: 40px;
  animation-delay: 0.3s;
}

.__UIV_SCOPE__ .loader .bar4 {
  left: 60px;
  animation-delay: 0.45s;
}

.__UIV_SCOPE__ .loader .bar5 {
  left: 80px;
  animation-delay: 0.6s;
}

.__UIV_SCOPE__ .loader .bar6 {
  left: 100px;
  animation-delay: 0.75s;
}

.__UIV_SCOPE__ .loader .bar7 {
  left: 120px;
  animation-delay: 0.9s;
}

.__UIV_SCOPE__ .loader .bar8 {
  left: 140px;
  animation-delay: 1.05s;
}

.__UIV_SCOPE__ .loader .bar9 {
  left: 160px;
  animation-delay: 1.2s;
}

@keyframes loader_51899 {
  0% {
    height: 30px;
    transform: translate(0, 0);
  }

  50% {
    height: 70px;
    transform: translate(0, 35px);
  }

  100% {
    height: 30px;
    transform: translate(0, 0);
  }
}
